argv:
$ErrorActionPreference='SilentlyContinue';
$procs=Get-CimInstance Win32_Process | Where-Object { $_.CommandLine -match '17448|WebAIBridge|server\.js|worker\.js' -and $_.CommandLine -notmatch 'E:\\manhwa' } | Select-Object ProcessId,ParentProcessId,Name,ExecutablePath,CommandLine;
$candidates=@('E:\WebAIBridge','E:\WebAIBridge\app','E:\web-ai-bridge','E:\web-ai-bridge\app');
$roots=@();
foreach($c in $candidates){
 if(Test-Path $c){
  $gitDir=Test-Path (Join-Path $c '.git');
  $head='';$branch='';
  if($gitDir){
    Push-Location $c;
    $head=(git rev-parse HEAD 2>$null);
    $branch=(git branch --show-current 2>$null);
    Pop-Location;
  }
  $roots += [pscustomobject]@{path=$c;exists=$true;git=$gitDir;head=$head;branch=$branch}
 }
}
$dirs=Get-ChildItem 'E:\' -Directory -Force | Where-Object {$_.Name -match 'Bridge|bridge|WebAI|webai'} | Select-Object FullName;
[pscustomobject]@{processes=@($procs);roots=@($roots);topDirs=@($dirs)} | ConvertTo-Json -Depth 6 -Compress
